/** Native type-loss research; legal supplied combat and actual paid flash-enabled casting. */
public class CommanderDefenderTypeChangeBlockedBaselineTest extends AITest {
    @Test public void nativeBlockedChangedBattleOrdinaryKeepsBlockerDamage() { typeChange(false,false,false,false,false,false,true); }
